-- QA Mock 데이터 1/2 — 기준 데이터(학원 · 계정 · 차량 · 매니저 · 승하차지 · 노선 · 스케줄 · 학생 · 보호자 · 요일별 주소).
--
-- 무엇을 위한 데이터인가 — QA 시나리오 문서(workspace 저장소 docs/qa/QA_SCENARIOS.md)가 이 파일의 계정·학생·노선을
-- 그대로 가리킨다. 행을 바꾸면 그 문서의 계정 표 · 데이터 지도도 함께 고친다.
-- 언제 깔리나 — local · staging · demo 프로파일(spring.flyway.locations 에 classpath:db/qa-seed). local 은 재기동과
-- POST /dev/reset 마다 clean() 후 다시 깐다. 자동 시험은 이 데이터를 쓰지 않는다(시험은 db/fixture).
--
-- 지역 — 경기 부천. 학원 A(중동 학원가)는 상동·중동의 "○○마을" 아파트 단지 30곳을 차량 3대가 나눠 돌고, 학원 B(괴안동)는
-- 역곡·괴안·범박동 단지 10곳을 1대가 돈다. 단지 이름 · 도로명 주소 · 좌표는 네이버 지역 검색 결과(2026-10-03)이고
-- 학원 이름은 가상이다.
-- 개인정보 — 이름은 가상, 전화는 010-0000-NNNN(실제 번호가 아닌 대역 — 매니저 앱 [전화]로 남에게 걸리지 않게),
-- 이메일은 example.com(예약 도메인). 학생 사진은 비워 둔다(파일 저장소가 시드 밖이라 — 등록 흐름으로 확인).
-- 비밀번호 — 전 계정 placeholder seedPasswordHash(local 은 "password").

-- ── 학원 3곳 — A(주 시나리오) · B(학원 격리 확인) · C(비활성, 로그인 유지 확인) ─────────────────────────
